const input = $json || {};
const body = input.body || input;
const headers = input.headers || {};

function header(name) {
  const key = Object.keys(headers).find((item) => item.toLowerCase() === name.toLowerCase());
  return key ? String(headers[key] || "") : "";
}

function firstValue(...values) {
  for (const value of values) {
    if (value !== undefined && value !== null && String(value).trim() !== "") return String(value).trim();
  }
  return "";
}

const expectedToken = $env.ONBOARDING_API_TOKEN;
const providedToken = header("x-onboarding-token");

const userId = firstValue(body.user_id, body.userId);
const organizationId = firstValue(body.organization_id, body.organizationId);
const agentId = firstValue(body.agent_id, body.agentId);
const action = firstValue(body.action).toLowerCase();

const serviceInput = body.service && typeof body.service === "object" ? body.service : {};
const serviceKey = firstValue(serviceInput.key);
const serviceName = firstValue(serviceInput.name);
const serviceDescription = firstValue(serviceInput.description);
const serviceAliases = Array.isArray(serviceInput.aliases)
  ? serviceInput.aliases.map((a) => String(a).trim()).filter(Boolean)
  : [];
const durationMinutesRaw = serviceInput.duration_minutes;
const durationMinutes = Number.isFinite(Number(durationMinutesRaw)) ? Number(durationMinutesRaw) : null;

// "prices" es una lista de { <dimension_classification_key>: valor, base_price }.
// El nombre real de la columna en DB es "vehicle_type" por razones historicas (ver
// docs de la consolidacion del rules_engine: es el eje de clasificacion secundario
// generico -- tipo de vehiculo para detailing, categoria de estilista para salon,
// etc.) -- se acepta el body como "vehicle_type" o "classification_value" para no
// forzar al panel a conocer ese detalle interno.
const pricesInput = Array.isArray(body.prices) ? body.prices : [];
const prices = pricesInput
  .map((p) => ({
    vehicle_type: firstValue(p.vehicle_type, p.classification_value, p.value),
    base_price: Number(p.base_price),
  }))
  .filter((p) => p.vehicle_type && Number.isFinite(p.base_price));

let error = null;
if (!expectedToken) error = "missing_onboarding_token_config";
else if (!providedToken || providedToken !== expectedToken) error = "invalid_onboarding_token";
else if (!userId) error = "missing_user_id";
else if (!organizationId) error = "missing_organization_id";
else if (!agentId) error = "missing_agent_id";
else if (!["add", "remove"].includes(action)) error = "invalid_action";
else if (!serviceKey) error = "missing_service_key";
else if (action === "add" && !serviceName) error = "missing_service_name";

return [{
  json: {
    valid: !error,
    error,
    user_id: userId || null,
    organization_id: organizationId || null,
    agent_id: agentId || null,
    action: action || null,
    service: {
      key: serviceKey || null,
      name: serviceName || null,
      description: serviceDescription || "",
      aliases: serviceAliases,
      duration_minutes: durationMinutes,
    },
    prices,
  }
}];

const upstream = $("validate_and_build_service_request").first().json;
const dbResult = $json || {};

function toBool(v) {
  return v === true || v === "t" || v === "true";
}

const isMember = toBool(dbResult.is_member);
const agentBelongs = toBool(dbResult.agent_belongs);
const configFound = toBool(dbResult.config_found);

let status = "ok";
if (!isMember) status = "forbidden";
else if (!agentBelongs) status = "agent_not_found";
else if (!configFound) status = "config_not_found";

if (status !== "ok") {
  return [{ json: { ...upstream, status } }];
}

function sqlText(value) {
  if (value === undefined || value === null || value === "") return "NULL";
  return "'" + String(value).replace(/'/g, "''") + "'";
}
function sqlNumber(value) {
  const n = Number(value);
  return Number.isFinite(n) ? String(n) : "NULL";
}
function sqlUuidOrNull(value) {
  const text = String(value || "").trim();
  const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(text);
  return isUuid ? "'" + text + "'::uuid" : "NULL::uuid";
}

const currentConfig = dbResult.current_config && typeof dbResult.current_config === "object" ? dbResult.current_config : {};
const currentVersion = Number(dbResult.current_version) || 0;
const activePricingVersionId = dbResult.active_pricing_version_id || null;

const currentServices = Array.isArray(currentConfig.services) ? currentConfig.services : [];
const service = upstream.service;
const action = upstream.action;
const prices = upstream.prices || [];

const serviceAlreadyExisted = currentServices.some((s) => s && s.key === service.key);

let newServices;
if (action === "add") {
  // upsert por key: si ya existia, se reemplaza (permite editar nombre/aliases/
  // descripcion sin necesitar una accion "edit" aparte); si no, se agrega.
  const cleanService = {
    key: service.key,
    name: service.name,
    aliases: service.aliases,
    description: service.description || "",
    duration_minutes: service.duration_minutes,
  };
  newServices = currentServices.filter((s) => !s || s.key !== service.key);
  newServices.push(cleanService);
} else {
  // remove: se quita del array. El historial no se pierde porque
  // agent_business_config es versionado (la fila vieja queda con is_active=false,
  // nunca se borra) -- no hace falta un flag de soft-delete dentro del JSON.
  newServices = currentServices.filter((s) => !s || s.key !== service.key);
}

const newConfig = { ...currentConfig, services: newServices };

let priceSql = null;
let pricesAction = "none";
if (action === "add" && activePricingVersionId && prices.length > 0) {
  pricesAction = "insert";
  const values = prices
    .map((p) => `(${sqlUuidOrNull(activePricingVersionId)}, ${sqlText(service.key)}, ${sqlText(p.vehicle_type)}, ${sqlNumber(p.base_price)}, true)`)
    .join(",\n    ");
  priceSql = `INSERT INTO public.service_vehicle_prices (pricing_version_id, service_code, vehicle_type, base_price, is_active)\nVALUES\n    ${values}\nRETURNING id;`;
} else if (action === "remove" && activePricingVersionId) {
  pricesAction = "deactivate";
  priceSql = `UPDATE public.service_vehicle_prices\nSET is_active = false\nWHERE pricing_version_id = ${sqlUuidOrNull(activePricingVersionId)}\n  AND service_code = ${sqlText(service.key)}\n  AND is_active = true\nRETURNING id;`;
}

return [{
  json: {
    ...upstream,
    status,
    service_already_existed: serviceAlreadyExisted,
    new_config: newConfig,
    new_version: currentVersion + 1,
    active_pricing_version_id: activePricingVersionId,
    price_sql: priceSql,
    prices_action: pricesAction,
    prices_requested_count: prices.length,
  }
}];

const prior = $("compute_new_config_and_prices").first().json;
const dbResult = $json || {};

return [{
  json: {
    ...prior,
    new_config_id: dbResult.new_config_id || null,
    new_version_written: dbResult.new_version_written || null,
    deactivated_count: dbResult.deactivated_count || 0,
  }
}];

const prior = $("merge_after_config_write").first().json;
const dbResult = $json || {};

return [{
  json: {
    ...prior,
    prices_written_count: Array.isArray($input.all()) ? $input.all().length : 0,
  }
}];

const input = $json || {};

if (input.status === "forbidden") {
  return [{ json: { ok: false, error: "forbidden", message: "El usuario no pertenece a esa organizacion." } }];
}
if (input.status === "agent_not_found") {
  return [{ json: { ok: false, error: "agent_not_found", message: "El agente no existe o no pertenece a esa organizacion." } }];
}
if (input.status === "config_not_found") {
  return [{ json: { ok: false, error: "config_not_found", message: "El agente no tiene una configuracion de negocio activa (agent_business_config). No se puede agregar/quitar un servicio hasta que exista una." } }];
}

const action = input.action;
const service = input.service || {};

let message;
if (action === "add") {
  message = input.service_already_existed
    ? `Servicio "${service.key}" actualizado.`
    : `Servicio "${service.key}" agregado.`;
  if (input.prices_requested_count > 0 && (input.prices_written_count || 0) === 0 && input.prices_action !== "none") {
    message += " Aviso: se esperaban precios pero no se pudieron insertar (revisar pricing_version activa del agente).";
  } else if (input.prices_requested_count === 0) {
    message += " Sin precios asociados todavia -- el servicio no se podra cotizar hasta que se agreguen.";
  }
} else {
  message = input.service_already_existed
    ? `Servicio "${service.key}" eliminado del catalogo (precios desactivados, historial preservado).`
    : `El servicio "${service.key}" no estaba en el catalogo -- nada que quitar (precios existentes, si los habia, quedaron desactivados igual).`;
}

return [{
  json: {
    ok: true,
    action,
    service_key: service.key,
    service_already_existed: input.service_already_existed,
    new_config_version: input.new_version_written || input.new_version,
    prices_action: input.prices_action,
    prices_written_count: input.prices_written_count || 0,
    message,
  }
}];
